export function prismState(t,value){const a=Math.max(10,Math.min(40,value)),entryY=394+(a-25)*2,exitY=404+(a-25)*.7;return{entryY,entryX:555-(entryY-256)/2,exitY,exitX:555+(exitY-256)/2,sourceY:entryY-(a-25)*4,pulse:.5+.5*Math.sin(t*Math.PI/5),bands:Array.from({length:7},(_,i)=>({x:555+(exitY+(i-3)*2-256)/2,y:exitY+(i-3)*2,endX:1060,endY:exitY+40+(i-3)*(30+(a-10)*.5)}))};}
