// White input and spectral fan remain visually separable.
c.strokeStyle='#f6f3d633';c.lineWidth=18;c.beginPath();c.moveTo(143,s.sourceY);c.lineTo(s.entryX,s.entryY);c.stroke();c.strokeStyle='#fff9e0';c.lineWidth=3;c.stroke();
for(let i=6;i>=0;i--){const b=s.bands[i];c.fillStyle=colors[i]+'18';c.beginPath();c.moveTo(b.x,b.y-2);c.lineTo(b.endX,b.endY-11);c.lineTo(b.endX,b.endY+11);c.lineTo(b.x,b.y+2);c.closePath();c.fill();c.strokeStyle=colors[i];c.lineWidth=2;c.beginPath();c.moveTo(b.x,b.y);c.lineTo(b.endX,b.endY);c.stroke();c.fillStyle=colors[i];c.fillRect(1074,b.endY-4,23,8);}
g=c.createLinearGradient(440,280,672,550);g.addColorStop(0,'#b9d4ff30');g.addColorStop(.5,'#727fa31a');g.addColorStop(1,'#aab7ed50');c.fillStyle=g;c.strokeStyle='#c7d7f5';c.lineWidth=1.5;c.beginPath();c.moveTo(555,256);c.lineTo(413,540);c.lineTo(697,540);c.closePath();c.fill();c.stroke();c.strokeStyle='#ffffffb0';c.lineWidth=2;c.beginPath();c.moveTo(s.entryX,s.entryY);c.lineTo(s.exitX,s.exitY);c.stroke();c.strokeStyle='#c9d9ff22';c.beginPath();c.moveTo(555,256);c.lineTo(573,519);c.lineTo(697,540);c.stroke();
